    "inv.export.lowStockDetailTitle": { "id": "Detail Stock Menipis & Saran Reorder", "en": "Low Stock Details & Reorder Suggestions", "ja": "在庫僅少詳細と再発注提案", "zh": "库存不足详情与补货建议" },
    "inv.err.fillDateRangeFirst": { "id": "Isi tanggal mulai & tanggal akhir dulu.", "en": "Please fill in the start and end dates first.", "ja": "先に開始日と終了日を入力してください。", "zh": "请先填写开始日期和结束日期。" },
