    "inv.confirm.deleteAssetFromItNcaText": { "id": "Yakin mau hapus Asset \"{name}\" dari Database Asset IT & NCA {facility}?", "en": "Are you sure you want to delete Asset \"{name}\" from the IT & NCA Asset Database {facility}?", "ja": "資産「{name}」を{facility}のIT・NCA資産データベースから削除してもよろしいですか？", "zh": "确定要从{facility}的IT与NCA资产数据库中删除资产“{name}”吗？" },
    "inv.err.importCancelledErrors": { "id": "Import dibatalkan, ada baris bermasalah:\n", "en": "Import cancelled, there are problematic rows:\n", "ja": "問題のある行があるためインポートを中止しました：\n", "zh": "导入已取消，以下行存在问题：\n" },
    "inv.confirm.importToStockText": { "id": "{count} Asset bakal ditambahkan ke Stock {facility}. Lanjut import?", "en": "{count} Assets will be added to Stock {facility}. Continue?", "ja": "{count}件の資産が{facility}の在庫に追加されます。続行しますか？", "zh": "将向{facility}库存添加{count}项资产。是否继续？" },
