    "inv.confirm.importToItNcaText": { "id": "{count} Asset bakal ditambahkan ke Database Asset IT & NCA {facility}. Lanjut import?", "en": "{count} Assets will be added to the IT & NCA Asset Database {facility}. Continue?", "ja": "{count}件の資産が{facility}のIT・NCA資産データベースに追加されます。続行しますか？", "zh": "将向{facility}的IT与NCA资产数据库添加{count}项资产。是否继续？" },
